type ListNode = { val: number; next: ListNode | null };
function buildList(values: number[], loopTo = -1): ListNode | null {
  const nodes: ListNode[] = values.map((val) => ({ val, next: null }));
  nodes.forEach((n, i) => { n.next = nodes[i + 1] ?? null; });
  if (loopTo >= 0 && nodes.length) nodes[nodes.length - 1].next = nodes[loopTo];
  return nodes[0] ?? null;
}

function reverse(head: ListNode | null): ListNode | null {
  let prev: ListNode | null = null;
  let cur = head;
  while (cur) {
    const nxt = cur.next;
    cur.next = prev;
    prev = cur;
    cur = nxt;
  }
  return prev;
}

function toArray(head: ListNode | null): number[] {
  const out: number[] = [];
  for (let n = head; n; n = n.next) out.push(n.val);
  return out;
}

function reverseValues(values: number[]): number[] {
  return toArray(reverse(buildList(values)));
}
